# GENERATED by plugin-cursor/scripts/compose.sh — edit core/ or plugin-claude/ then re-compose
"""Recover a subagent's receipt from the transcript when the subagent
emitted valid JSON in its response text but forgot to call Write.

Defense-in-depth for the SubagentStop verify hook: when the receipts
directory is empty after a subagent run, scan the parent transcript
(Claude Code JSONL) for an assistant message containing a structurally-
valid receipt JSON block. If one is found, write it to disk at the
canonical path so the verify hook can proceed as if Write had been
called.

Pure logic. No subprocess, no network. Layer-1 testable.
"""
from __future__ import annotations

import json
import re
from pathlib import Path
from typing import Any, Iterable

# Minimum keys that mark a JSON object as a receipt (a subset of the
# validator's REQUIRED_FIELDS, picked to be unambiguous). Anything
# smaller risks matching unrelated JSON in the transcript.
_RECEIPT_FINGERPRINT = {"role", "artifacts", "verification_commands"}

# Map "role" string → canonical short abbreviation used in receipt
# filenames. Mirrors the table in
# `plugin-claude/skills/_shared/protocols/receipt-protocol.md`.
ROLE_ABBREV = {
    "software-engineer": "se",
    "quality-engineer": "qe",
    "code-reviewer": "cr",
    "solution-architect": "sa",
    "project-owner": "po",
    "product-manager": "po",  # legacy alias
    "compliance-engineer": "ce",
    "platform-engineer": "pe",
    "technical-writer": "tw",
    "research-advisor": "ra",
}

# Match fenced JSON blocks (```json ... ``` or ``` ... ```) and also a
# bare JSON object at the end of a string. We try fenced first, then
# fall back to a brace-balanced search from the last `{`.
_FENCE_RE = re.compile(r"```(?:json)?\s*\n?(\{.*?\})\s*\n?```", re.DOTALL)


def _iter_assistant_texts(transcript_path: Path) -> Iterable[str]:
    """Yield the text content of every assistant message in the
    transcript, in reverse order (most recent first).

    Claude Code transcripts are JSONL; each line is a message envelope
    with `message.content` being either a string or a list of content
    blocks. We extract the concatenated text from `type=="text"` blocks.
    """
    try:
        lines = transcript_path.read_text(encoding="utf-8").splitlines()
    except (OSError, UnicodeDecodeError):
        return
    for line in reversed(lines):
        line = line.strip()
        if not line:
            continue
        try:
            entry = json.loads(line)
        except json.JSONDecodeError:
            continue
        msg = entry.get("message") if isinstance(entry, dict) else None
        if not isinstance(msg, dict):
            continue
        if msg.get("role") != "assistant":
            continue
        content = msg.get("content")
        if isinstance(content, str):
            yield content
        elif isinstance(content, list):
            parts: list[str] = []
            for block in content:
                if isinstance(block, dict) and block.get("type") == "text":
                    t = block.get("text")
                    if isinstance(t, str):
                        parts.append(t)
            if parts:
                yield "\n".join(parts)


def _candidate_jsons(text: str) -> Iterable[dict]:
    """Yield JSON objects found in `text`.

    Strategy:
      1. Every fenced ```json``` / ``` block.
      2. The trailing JSON object — last `{` to last balanced `}`.
    Yields parsed dicts only; ignores anything that isn't a dict or
    fails to parse.
    """
    seen_offsets: set[int] = set()
    for m in _FENCE_RE.finditer(text):
        seen_offsets.add(m.start(1))
        try:
            obj = json.loads(m.group(1))
        except json.JSONDecodeError:
            continue
        if isinstance(obj, dict):
            yield obj

    # Brace-balanced fallback: walk from the last `{` forward, tracking
    # nesting. Stops at the first balanced object that parses.
    start = text.rfind("{")
    while start >= 0:
        if start in seen_offsets:
            start = text.rfind("{", 0, start)
            continue
        depth = 0
        for i in range(start, len(text)):
            ch = text[i]
            if ch == "{":
                depth += 1
            elif ch == "}":
                depth -= 1
                if depth == 0:
                    candidate = text[start : i + 1]
                    try:
                        obj = json.loads(candidate)
                    except json.JSONDecodeError:
                        break
                    if isinstance(obj, dict):
                        yield obj
                    break
        start = text.rfind("{", 0, start)


def _looks_like_receipt(obj: dict) -> bool:
    return _RECEIPT_FINGERPRINT.issubset(obj.keys())


def find_receipt_in_transcript(transcript_path: str | Path) -> dict[str, Any] | None:
    """Return the most recent receipt-shaped JSON object from the
    transcript, or None if nothing matches."""
    p = Path(transcript_path)
    if not p.exists():
        return None
    for text in _iter_assistant_texts(p):
        for obj in _candidate_jsons(text):
            if _looks_like_receipt(obj):
                return obj
    return None


def recover_from_transcript(
    transcript_path: str | Path,
    receipts_dir: str | Path,
    story_id_hint: str | None = None,
) -> Path | None:
    """Scan the transcript for a receipt JSON, write it to disk, return
    the new path. Returns None when no receipt could be recovered.

    Filename resolution:
      - `story_id` is read from the receipt body when present, else
        falls back to `story_id_hint` (passed by the hook from
        `.synaptory/.orchestrator/pipeline-state.json`).
      - `role_abbrev` is derived from the receipt's `role` field via
        ROLE_ABBREV. Unknown roles fall back to a `safe_role` slug.
    """
    receipt = find_receipt_in_transcript(transcript_path)
    if receipt is None:
        return None

    story_id = receipt.get("story_id") or story_id_hint
    role = receipt.get("role") or ""
    role_abbrev = ROLE_ABBREV.get(role)
    if not role_abbrev:
        # Fall back to a sanitised slug so the filename is at least
        # deterministic — verify hook will still flag the validator
        # warning for unknown role.
        role_abbrev = re.sub(r"[^a-z0-9]+", "-", role.lower()).strip("-") or "unknown"
    if not story_id:
        # No way to construct the canonical path; refuse to write
        # rather than picking an arbitrary name. Hook will log
        # receipt_missing as before.
        return None

    out_dir = Path(receipts_dir)
    out_dir.mkdir(parents=True, exist_ok=True)
    target = out_dir / f"{story_id}-{role_abbrev}.json"
    target.write_text(json.dumps(receipt, indent=2, ensure_ascii=False), encoding="utf-8")
    return target


def _cli() -> int:  # pragma: no cover — thin CLI wrapper
    """Entry point for the shell hook:

        receipt_recovery.py <transcript_path> <receipts_dir> [story_id_hint]

    Prints the path of the recovered file on stdout, or nothing if no
    receipt could be recovered. Always exits 0 so the hook can decide
    based on stdout being empty.
    """
    import sys

    if len(sys.argv) < 3:
        return 0
    hint = sys.argv[3] if len(sys.argv) > 3 else None
    result = recover_from_transcript(sys.argv[1], sys.argv[2], hint)
    if result is not None:
        print(str(result))
    return 0


if __name__ == "__main__":  # pragma: no cover
    raise SystemExit(_cli())
